"""Regenerate docs/COMMANDS.md from the live command registry and object view catalogues.
    python docs/make_reference.py"""
import os
import sys
import warnings

warnings.simplefilter("ignore")
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, ROOT)
from finomania.core.commands import HELP, Interpreter  # noqa: E402

EX = os.path.join(ROOT, "examples")
out = ["# Finomania command reference", "",
       "Commands are typed in the Command window (Enter runs the current line), written in program files "
       "(`.fprg`) or generated by the dialogs. Options go in parentheses right after the command name; "
       "`name.method` calls a view or procedure of an object.", ""]
cats = {}
for k, (cat, syn, desc) in HELP.items():
    cats.setdefault(cat, []).append((k, syn, desc))
order = ["Workfile", "Objects", "Statistics", "Time series tests", "Estimation", "Volatility (ARCH)",
         "Volatility (multivariate)", "Time series models", "Panel", "Factor models", "Machine learning", "Risk",
         "Graphs", "General"]
for cat in order + [c for c in cats if c not in order]:
    if cat not in cats:
        continue
    out += [f"## {cat}", "", "| Command | Syntax | Description |", "|---|---|---|"]
    for k, syn, desc in sorted(cats[cat]):
        out.append(f"| `{k}` | `{syn.replace('|', '&#124;')}` | {desc.replace('|', '&#124;')} |")
    out.append("")

out += ["## Expressions", "",
        "Series expressions follow EViews conventions: `x(-1)` lag, `x(1)` lead, `d(x)`, `d(x,n,s)`, `dlog(x)`, "
        "`log`, `exp`, `abs`, `sqrt`, `^` power, `=` / `<>` comparisons, `and` / `or` / `not`.", "",
        "| Function | Meaning |", "|---|---|"]
funcs = [("@mean, @sum, @stdev, @var, @vars, @min, @max, @median, @quantile(x,q), @obs, @nas, @skew, @kurt",
          "Scalar statistics over the current sample"),
         ("@cor(x,y), @cov(x,y), @covs(x,y)", "Correlation / covariance"),
         ("@movav(x,n), @movsum, @movstdev, @movvar, @movmin, @movmax, @ewma(x,lambda)", "Moving-window statistics"),
         ("@cumsum, @cumprod, @cummax, @cummin", "Cumulative functions"),
         ("@pch(x), @pcha(x), @pchy(x)", "Percent change: one period, annualised, year-on-year"),
         ("@recode(cond,a,b), @iif, @nan(x,y), @isna(x)", "Recoding and missing values"),
         ("@trend, @obsnum, @year, @quarter, @month, @day, @weekday, @seas(k), @crossid", "Deterministic / calendar"),
         ("@demean, @detrend, @standardize, @meansby(x,g)", "Transformations"),
         ("nrnd, rnd, @rtdist(df), @rchisq(df)", "Random numbers (seed with rndseed)"),
         ("@cnorm, @dnorm, @qnorm, @logit, @log10, @round, @floor, @ceil, @inv", "Math"),
         ("eq1.@r2, eq1.@aic, eq1.@logl, eq1.@coefs(i), eq1.@stderrs(i), eq1.@tstats(i)",
          "Results of estimated objects"),
         ("!x = 1, %s = \"text\", {!x}, {%s}", "Program variables and text substitution"),
         ("for/next, if/then/else/endif, while/wend, exitloop, stop", "Program control flow")]
for a, b in funcs:
    out.append(f"| `{a}` | {b} |")
out.append("")

# object views / procs from live objects
it = Interpreter()
prog = f'''
import "{EX}/data/stocks_daily.csv"
series r1 = 100*dlog(alpha)
series r2 = 100*dlog(beta)
equation e_ls.ls r1 c r1(-1)
equation e_arch.arch(1,1,tarch,dist=t) r1 c
equation e_arima.arima(1,0,1) r1 c
equation e_dcc.dcc r1 r2
var e_var.ls 1 2 r1 r2 @ c
equation e_ml.ml(method=ridge) r1
'''
it.run(prog)
objs = [("Least squares equation", "e_ls"), ("ARCH / GARCH equation", "e_arch"), ("ARIMA equation", "e_arima"),
        ("DCC / BEKK system", "e_dcc"), ("VAR", "e_var"), ("Machine-learning model", "e_ml")]
it2 = Interpreter()
it2.run(f'import(id=firm, date=year) "{EX}/data/firm_panel.csv"\nequation p_fe.ls(cx=f) inv c q cf\n'
        f'equation p_ab.dpd inv q cf')
it3 = Interpreter()
it3.run(f'import "{EX}/data/portfolios_monthly.csv"\nequation f1.ff(model=ff3, file="{EX}/data/ff5_factors_simulated.csv",'
        f' units=pct) p1 p2 p3 p4 p5 p6')
out += ["## Object views and procedures", "",
        "Call them as `name.key(options)` or from the View / Proc menus of an object window.", ""]
for lab, wfobj in [(l, it.wf.objects[n]) for l, n in objs] + [("Panel equation", it2.wf.objects["p_fe"]),
                                                              ("Dynamic panel GMM", it2.wf.objects["p_ab"]),
                                                              ("Factor model", it3.wf.objects["f1"])]:
    out += [f"### {lab}", "", "| Key | Kind | Label | Options |", "|---|---|---|---|"]
    for v in wfobj.result.views() + wfobj.result.procs():
        opts = ", ".join(f"{p.name}={p.default}" for p in v.params)
        out.append(f"| `{v.key}` | {v.kind} | {v.label} | {opts} |")
    out.append("")
with open(os.path.join(ROOT, "docs", "COMMANDS.md"), "w", encoding="utf-8") as f:
    f.write("\n".join(out))
print("wrote docs/COMMANDS.md", len(out), "lines")
